$_MODULE['<{ntbackupandrestore}prestashop>advanced_configuration_194b85107c0971a099e6d6efc4cbc90a'] = 'Línea de valores máximos por línea de volcado. Un número más bajo significa más acceso al disco. No toque esta opción a menos que el soporte 2N lo requiera. Esto tiene consecuencias en las capacidades de restauración.';
$_MODULE['<{ntbackupandrestore}prestashop>advanced_configuration_a7e944d50425fc7dbf4237a92eaf4bfe'] = 'Número máximo de líneas que se insertará a la vez en la base de datos durante la restauración. Si hay demasiados datos a la vez, su servidor mysql puede estresarse demasiado y detener la restauración.';
