$_MODULE['<{ntbackupandrestore}prestashop>advanced_configuration_820129f1a611adea6ae07f80f508f614'] = 'Deshabilite la renovación intermedia. La copia de seguridad se realizará sin interrupción, pero el tiempo de espera del servidor debe ser lo suficientemente grande.';
