$_MODULE['<{ntbackupandrestore}prestashop>advanced_configuration_696e902e76f7e4ef397b9c093a688e8f'] = 'Duración entre la actualización del progreso (valor predeterminado %1$d segundo). Útil para servidores pequeños, ahorra algunos recursos, pero el progreso puede ser menos reactivo.';
