$_MODULE['<{ntbackupandrestore}prestashop>faq_96d45a338ff7b992b596577083f9d114'] = '¿Con qué frecuencia se realiza la automatización por 2N?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_51452b6d1f8511cf289eb01753eda3bb'] = 'La automatización por 2N se realiza diariamente';
$_MODULE['<{ntbackupandrestore}prestashop>faq_42027eaa203032a09ccc5048897c677c'] = 'La automatización por 2N parece que ya no funciona, ¿qué puedo hacer?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_ffebb8fcef9bdccc3aeac353e6d78be7'] = 'Por favor, intente guardarlo de nuevo';
$_MODULE['<{ntbackupandrestore}prestashop>faq_41906c69303e903c986fde8f7cb34665'] = 'La copia de seguridad terminó con un error que indica que no hay suficiente espacio para la copia de seguridad, pero sé que sí. ¿Por qué tengo este error?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_8bdbb9087cc2864414759889f6d22307'] = 'Este error puede deberse a un límite del servidor. Algunos servidores (32 bits) no permitirán que la copia de seguridad sea de más de 2 GB. En este caso, puede usar la opción avanzada para limitar el tamaño de la copia de seguridad. Su copia de seguridad se cortará en partes más pequeñas que serán aceptadas por su servidor. Por ejemplo, puede elegir 1500 como límite de tamaño para el tamaño del archivo de copia de seguridad. Preste atención a que todas las piezas son obligatorias si desea restaurar su tienda.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_afde1c7273735610102d9f166386b91e'] = '¿Dónde puedo encontrar la copia de seguridad en mi servidor?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_c99296863a8cfebedbf941a80b149eb3'] = 'Puede encontrar su copia de seguridad en el directorio modules/ntbackupandrestore/backup/ de forma predeterminada, o en el directorio que configuró en configuración avanzada.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_6162f1ad35f8d68d2ad18e65d6af12ca'] = '¿Dónde puedo encontrar el volcado de la base de datos en mi copia de seguridad?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_259f134b1c3cb0f4211d27812fb4f339'] = 'Al crear una copia de seguridad completa, la base de datos se guarda con todos los demás archivos del archivo de copia de seguridad. Si desea verificar, destar su archivo de copia de seguridad en su computadora, puede encontrar el volcado.sql en el directorio modules / ntbackupandrestore / backup /';
$_MODULE['<{ntbackupandrestore}prestashop>faq_d50856eaf5567a344aafac6b6629a581'] = '¿Cómo puedo comprobar que mi copia de seguridad es válida?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_d2a25247fc786e9f6a27212ee9aed0b8'] = 'La mejor manera de asegurarse de que su copia de seguridad sea válida es intentar restaurarla en otro lugar. Por ejemplo, en un nuevo dominio y una nueva base de datos o en su computadora con Wamp, Mamp, Easyphp u otros softwares de servidor local.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_b26bae87fdb843d75a120d12fe51ffa6'] = '¿Cómo puedo restaurar mi copia de seguridad?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_84d3c56657e5438d10f92c3d36c5cf8b'] = 'Para restaurar su copia de seguridad, debe:';
$_MODULE['<{ntbackupandrestore}prestashop>faq_261aa829c8bd1bd4216bf09dc76f7326'] = 'Elija dónde se restaurará la tienda. Ya sea en un nuevo lugar (nuevo dominio y nueva base de datos) para una copia / movimiento o en la raíz de su tienda actual para su reemplazo.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_0c02578d80e75b15e3c2fafda964bfe4'] = 'Coloque su script de copia de seguridad y restauración en la ubicación que elija';
$_MODULE['<{ntbackupandrestore}prestashop>faq_967e66ec729f29106f185bf0e5c9c267'] = 'Acceda al script de restauración, utilizando su navegador web';
$_MODULE['<{ntbackupandrestore}prestashop>faq_96c158c212b69d93f4bf51a208b7c6b0'] = 'Rellene las credenciales de acceso de la base de datos donde se restaurarán los datos.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_3438a63edfc1456e8bff9b8a75f0f8c2'] = 'Opcional: si es necesario, configure las opciones avanzadas';
$_MODULE['<{ntbackupandrestore}prestashop>faq_0b20e24f98a55bf66d6fe76363284591'] = 'Inicie la restauración. Preste atención a que los archivos de su copia de seguridad sobrescribirán los posibles archivos existentes y la base de datos será reemplazada por la base de datos de su copia de seguridad.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_6510898b2f7a8fa6fe8aeafb9ea5ca4d'] = 'Para restaurar mi tienda, ¿necesito instalar primero una Prestashop vacía?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_2f8b950c8cb11678dd68bd1050f15034'] = 'No es necesario instalar un Prestashop vacío para restaurar. Solo necesita su archivo de copia de seguridad y script de restauración.';
