$_MODULE['<{ntbackupandrestore}prestashop>faq_d22b5ed685107fdea35dd423a0adc8e4'] = 'La copia de seguridad completa contendrá una copia exacta de su sitio web, lo que significa todos sus archivos y datos, excepto archivos y datos de bajo interés (cachés, registros ...) que no se guardan porque su tamaño es grande y son de poca utilidad durante una restauración. Sin embargo, puede decirle al módulo que los guarde en las opciones avanzadas.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_c7b627aacbd45fc86611dc65afcd11fc'] = 'No tengo suficiente espacio en mi servidor para la copia de seguridad, ¿puedo enviarla directamente a una de mis cuentas remotas (%1$s, %2$s...)?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_0ec06b6f186a84a008827f4ee4efdff2'] = 'Antes de que se pueda enviar a una cuenta remota, la copia de seguridad debe crearse en su servidor. Al menos debe tener espacio para una copia de seguridad. Puede elegir en la configuración avanzada la opción que permite la eliminación automática de la copia de seguridad local si se envía a una cuenta remota. Si no tiene suficiente espacio para una copia de seguridad, puede habilitar el envío directo (sin copia de seguridad local) al servidor remoto (excepto FTP y Box), pero en este caso, la copia de seguridad no se comprimirá.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_50fe9d94822e8a6d1ed52600d8c071cc'] = '¿Cómo actualizar el módulo?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_c45a02babc859c783cc1a5b21b62cdfd'] = 'Debe descargar la última versión del módulo desde donde lo compró.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_cf832f19d14486b25d11aaf8e9cc016d'] = 'Luego, en el backoffice de su tienda, en Modules > Modules Manager, haga clic en el botón Instalar módulo y elija el archivo zip del módulo.';
