$_MODULE['<{ntbackupandrestore}prestashop>faq_45f9bd66e610f3a4fb32025275105451'] = 'Cuando restauro mi copia de seguridad con el script de restauración, recibo el mensaje de error: \"Error al restaurar archivos, archivo tar truncado\"';
$_MODULE['<{ntbackupandrestore}prestashop>faq_6ddd16646b753dd26ee53747b23a2ec2'] = 'Este error aparece cuando el script de restauración no puede extraer todos los archivos de la copia de seguridad.';
